/* Generated by tools/import_d2_gems.py from gems.txt, misc.txt and item-names.json.
 * Do not edit by hand: rerun the importer to pick up new game data. */
import type { D2ItemStats } from "./d2-item-stats";

/** One gem's effect in one kind of socket host. */
export interface D2GemRoll {
  stats: D2ItemStats;
  /** Tooltip lines, worded from the gem table's own values. */
  lines: string[];
}

export interface D2GemDefinition {
  name: string;
  /** Ruby, Sapphire, Emerald, Amethyst, Diamond, Topaz or Skull. */
  color: string;
  /** Chipped, Flawed, Normal, Flawless or Perfect. */
  grade: string;
  requiredLevel: number;
  /** gems.txt weaponMod* rows. */
  inWeapon: D2GemRoll;
  /** gems.txt helmMod* rows, which body armor also uses. */
  inHelm: D2GemRoll;
  /** gems.txt shieldMod* rows. */
  inShield: D2GemRoll;
}

